// Independent acceptance oracle for the two published verification journeys.
// These expectations are not generated by the interface coding model.
export function sourceOutcomeMatches(kind, task, operation) {
  const record = operation?.return
  if (
    task?.status !== 'complete' ||
    operation?.status !== 'committed' ||
    !record ||
    record.taskId !== task.id ||
    operation.operationId !== task.operationId ||
    !task.receipt?.requestId ||
    task.receipt.requestId !== record.requestId ||
    !task.approval?.proposalDigest ||
    operation.proposalDigest !== task.approval.proposalDigest
  )
    return false
  if (kind === 'return')
    return (
      record.method === 'qr_dropoff' &&
      record.refundDestination === 'original_payment' &&
      record.currency === 'USD' &&
      record.deductionCents === 500 &&
      record.expectedRefundCents === 7500 &&
      record.selectedLineIds?.length === 1 &&
      record.selectedLineIds[0] === 'SHOE-RED-8' &&
      record.status === 'return_requested_refund_pending'
    )
  if (kind === 'appointment')
    return (
      record.slotId === 'sat-1100' &&
      record.startsAt === '2026-10-31T11:00:00-07:00' &&
      record.technician === 'Maya Chen' &&
      record.feeCents === 0 &&
      record.currency === 'USD' &&
      record.activeBookings === 1
    )
  return false
}
